contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 d, address to) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d)); require(d <= 1000000000000000000000000000000);
        require(d > 0, "nonzero deposit");
        require(address(this).balance >= d, "need ether");
        require(to != address(0), "nonzero recipient");

        c.deposit{value: d}(); if (__ESBMC_reverted()) return;

        uint256 beforeRecipient = to.balance;
        uint256 cBalanceBefore = address(c).balance;

        c.migrateTo(to); if (__ESBMC_reverted()) return;

        assert(address(c).balance == 0 && to.balance == beforeRecipient + cBalanceBefore);
    }

    receive() external payable {}
}

